mapper.select:
select id, is_deleted, nezha_tenant_code, name, description, status, agent_unique_id, category, endpoint_url, agent_type, version, owner_id, definition_id, definition_version, identity_id, current_skill_id, endpoint_type, create_at, create_by, create_name, update_at, update_by, update_name from agent_registry where is_deleted = 0
and name like concat('%', #{name,jdbcType=VARCHAR}, '%')
and status = #{status,jdbcType=VARCHAR}
and category = #{category,jdbcType=VARCHAR}
and agent_type = #{agentType,jdbcType=VARCHAR}
order by id desc
